const lessons=[{"sentences":[{"speaker":"A","text":"We really need to talk about how the apartment looks because it is completely messy right now.","pauseAfterSeconds":0.2,"position":1,"audioStartSeconds":0,"audioEndSeconds":5.2},{"speaker":"B","text":"I completely agree with you although I have been working very late shifts every single night this week.","pauseAfterSeconds":0.2,"position":2,"audioStartSeconds":5.4,"audioEndSeconds":10.52},{"speaker":"A","text":"I know you were busy, but the kitchen counter is covered in dirty dishes from the weekend.","pauseAfterSeconds":0.2,"position":3,"audioStartSeconds":10.72,"audioEndSeconds":15.52},{"speaker":"B","text":"If you can wash those dishes for me today, I promise I will clean the bathroom tomorrow.","pauseAfterSeconds":0.2,"position":4,"audioStartSeconds":15.72,"audioEndSeconds":20.44},{"speaker":"A","text":"That does not sound entirely fair because I cleaned the bathroom all by myself last week.","pauseAfterSeconds":0.2,"position":5,"audioStartSeconds":20.64,"audioEndSeconds":25.6},{"speaker":"B","text":"You have a good point, so let us divide all the chores equally on a paper list.","pauseAfterSeconds":0.2,"position":6,"audioStartSeconds":25.8,"audioEndSeconds":30.2},{"speaker":"A","text":"That is a much better idea when we both want to keep the place nice and tidy.","pauseAfterSeconds":0.2,"position":7,"audioStartSeconds":30.4,"audioEndSeconds":34.48},{"speaker":"B","text":"I can take responsibility for taking out the heavy trash bags and vacuuming the living room floor.","pauseAfterSeconds":0.2,"position":8,"audioStartSeconds":34.68,"audioEndSeconds":39.8},{"speaker":"A","text":"That works perfectly because I do not mind wiping down the counters and cleaning the stove.","pauseAfterSeconds":0.2,"position":9,"audioStartSeconds":40,"audioEndSeconds":45.36},{"speaker":"B","text":"Should we also agree to wash our own cooking pans immediately after we finish eating dinner?","pauseAfterSeconds":0.2,"position":10,"audioStartSeconds":45.56,"audioEndSeconds":50.04},{"speaker":"A","text":"Yes, that rule will definitely prevent the sink from overflowing with pots again.","pauseAfterSeconds":0.2,"position":11,"audioStartSeconds":50.24,"audioEndSeconds":55.04},{"speaker":"B","text":"Shall we write these new rules down on the whiteboard so we never forget them?","pauseAfterSeconds":0.2,"position":12,"audioStartSeconds":55.24,"audioEndSeconds":58.92},{"speaker":"A","text":"Let us do that right now before we both sit down to watch our favorite television show.","pauseAfterSeconds":0.2,"position":13,"audioStartSeconds":59.12,"audioEndSeconds":64}],"questions":[{"prompt":"Why did speaker B fail to clean earlier in the week?","options":["Because of working late shifts.","Because of visiting family out of town.","Because of studying for university exams."],"answer":"A","evidenceSentence":2,"evidence":"working very late shifts every single night","explanation":"Speaker B giải thích rằng họ đã phải làm ca đêm rất muộn trong suốt cả tuần."},{"prompt":"What was speaker A' objection to the initial proposal?","options":["Speaker A hates doing the dishes.","Speaker A cleaned the bathroom last week.","Speaker A thinks the apartment is already clean."],"answer":"B","evidenceSentence":5,"evidence":"I cleaned the bathroom all by myself last week","explanation":"Speaker A từ chối đề xuất ban đầu vì chính họ đã dọn phòng tắm một mình vào tuần trước."},{"prompt":"What is the main purpose of this conversation?","options":["To complain about high apartment rent.","To negotiate a fair cleaning schedule.","To plan a dinner party for the weekend."],"answer":"B","evidenceSentence":6,"evidence":"divide all the chores equally","explanation":"Hai người bạn cùng phòng đang thảo luận để phân chia việc nhà công bằng hơn sau một tuần bận rộn."},{"prompt":"What chores does speaker B agree to handle?","options":["Wiping counters and cleaning the stove.","Taking out the trash and vacuuming.","Washing all the dirty weekend dishes."],"answer":"B","evidenceSentence":8,"evidence":"taking out the heavy trash bags and vacuuming","explanation":"Speaker B đồng ý nhận việc đổ rác nặng và hút bụi phòng khách."},{"prompt":"What new rule do they establish regarding cooking pans?","options":["To buy new pans every month.","To leave pans in the sink overnight.","To wash pans immediately after dinner."],"answer":"C","evidenceSentence":10,"evidence":"wash our own cooking pans immediately after we finish eating","explanation":"Họ thống nhất quy tắc rửa chảo ngay sau khi ăn tối xong để tránh bồn rửa bị đầy."},{"prompt":"What will the speakers do next?","options":["Write the rules on the whiteboard.","Sit down to watch television.","Order takeaway food for dinner."],"answer":"A","evidenceSentence":12,"evidence":"write these new rules down on the whiteboard","explanation":"Họ quyết định viết các quy tắc mới lên bảng trắng ngay lập tức trước khi đi xem TV."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
